def check_if_cm_execution():
    return True if os.environ.get("CM_EXECUTION_ID") else False


def wait_until_success(timeout: int, interval: int, function_name, *args, **kwargs):
    end_time = timeout + time.time()
    last_exception = ""
    while time.time() < end_time:
        try:
            return function_name(*args, **kwargs)
        except FatalError as fatal_error:
            raise FatalError(fatal_error)
        except Exception as exception:
            if "Execution terminated by signal" in exception.__str__():
                raise Exception
            last_exception = exception
            time.sleep(interval)
    raise FunctionTimeoutException(function_name, timeout, last_exception)


def verify_function_x_times(retry: int, interval: int, function_name, *args, **kwargs):
    attempt = 0
    while attempt < retry:
        try:
            return function_name(*args, **kwargs)
        except FatalError as fatal_error:
            raise FatalError(fatal_error)
        except Exception as exception:
            if "Execution terminated by signal" in exception.__str__():
                raise Exception
            attempt += 1
            time.sleep(interval)
    raise Exception(f"{function_name} failed after {retry} times")


def verify_function_x_times_with_ret(retry: int, interval: int, function_name, *args, **kwargs):
    attempt = 0
    exc_list = []
    while attempt < retry:
        try:
            return function_name(*args, **kwargs), exc_list
        except Exception as e:
            if "Execution terminated by signal" in e.__str__():
                raise Exception
            attempt += 1
            time.sleep(interval)
            exc_list.append(e)
    raise Exception(f"{function_name} failed after {retry} times due to {exc_list}")


def run_and_ignore_error(function, *args, **kwargs):
    try:
        return function(*args, **kwargs), True
    except Exception as exception:
        return exception, False


def run_and_continue_on_failure(function, *args, **kwargs):
    try:
        return function(*args, **kwargs)
    except KeyboardInterrupt:
        raise
    except Exception as exception:
        test_logger(f"Execution of {function.__name__} failed", log_level="ERROR")
        test_logger(traceback.format_exc(), console=False)
        return False


def test_logger(msg, log_level: str = "INFO", console: bool = True, html: bool = False,
                hyperlink: bool = False):
    now = f"{time.strftime('%H:%M:%S')} - " if console else ""
    if log_level.upper() == "INFO":
        if hyperlink:
            log_message_with_hyperlink(msg)
        logger.info(msg=f"{now}{msg}", also_console=console, html=html)
    elif log_level.upper() == "WARN" or log_level.upper() == "ERROR":
        logger.write(msg=f"{now}{msg}", html=html, level=log_level.upper())
    elif log_level.upper() == "DEBUG":
        logger.debug(msg=f"{now}{msg}", html=html)


@contextmanager
def time_limit(seconds: int) -> None:
    def signal_handler(signum, frame):
        raise TimeoutError("Timed out!")

    signal.signal(signal.SIGALRM, signal_handler)
    signal.alarm(seconds)
    try:
        yield
    finally:
        signal.alarm(0)


def check_uuf_tags():
    uuf_tags = ("UUF_CUSTOMER", "UUF_CONFIGURATION", "UPDATE_PATH", "UUF_BUILD", "SM_BUILD")
    if not os.environ.get("CM_EXECUTION_ID"):
        return True
    if os.environ.get("CM_TAGS"):
        cm_tags = json.loads(os.getenv("CM_TAGS", "[]"))
        uuf_tag = [tag.split('=')[0].upper() for tag in cm_tags if tag.split("=")[0].upper() in uuf_tags]
        test_logger(f"The UUF_tag: {uuf_tag} was added")
        return True
    return None


def run_kw_and_continue_on_failure(method, *args, **kwargs):
    try:
        return method(*args, **kwargs)
    except ExecutionFailed as err:
        if not err.dont_continue:
            err.continue_on_failure = True
        raise err


def run_process(command: str) -> str:
    process = subprocess.Popen(command, universal_newlines=True, shell=True,
                               stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    output, error = process.communicate()
    if process.returncode != 0:
        test_logger(f"Output: {output}", "DEBUG")
        test_logger(f"Error: {error}", "DEBUG")
        raise subprocess.CalledProcessError(returncode=process.returncode, cmd=process.args, stderr=output)
    return output


def get_source_sw():
    return __get_sw_from_artifacts("Source")


def get_target_sw():
    return __get_sw_from_artifacts("Target")


def __get_tag_value(tag_name, tag_list):
    if tag_list:
        tag = [tag.split("=")[1] for tag in tag_list if tag_name.lower() in tag.lower()]
        if tag:
            return tag[0]
    return None


def __get_sw_from_artifacts(sw_type):
    if not os.environ.get("CM_EXECUTION_ID"):
        raise Exception("Not Cloud Execution, Suite Will be aborted!")
    cm_artifacts = json.loads(os.getenv("CM_ARTIFACTS", "[]"))
    if sw_type == "Source":
        cm_tags = json.loads(os.getenv("CM_TAGS", "[]"))
        if not cm_artifacts or not cm_tags:
            raise Exception("Artifacts weren't found in Env Variables")
        customer_name = __get_tag_value("UUF_CUSTOMER", cm_tags)
        customer_config_id = __get_tag_value("UUF_CONFIGURATION", cm_tags)
        update_path = __get_tag_value("UPDATE_PATH", cm_tags)
        uuf_build = __get_tag_value("UUF_BUILD", cm_tags)
        for artifact in cm_artifacts:
            try:
                if customer_name and customer_config_id:
                    for customer in artifact['properties']['upgrade_path']['customer_deployments']:
                        if customer["customer"].lower() == customer_name.lower():
                            for deployment in customer["deployments"]:
                                if deployment["uuf_configuration_id"] == int(customer_config_id):
                                    test_logger(f"Found source sw : {deployment['source_sw_build']}\n"
                                                f"SW was selected based on Customer {customer} "
                                                f"and Config Id {customer_config_id}")
                                    return deployment["source_sw_build"]
                elif update_path:
                    build = artifact['properties']['upgrade_path']['product_defaults'][update_path].upper()
                    if build:
                        test_logger(f"Found source sw : {build}\n"
                                    f"SW was selected based on update path :{update_path}")
                        return build
                elif uuf_build:
                    build = uuf_build.upper()
                    if build:
                        test_logger(f"Found source sw : {build}\n"
                                    f"SW was selected based on UUF_BUILD tag :{uuf_build}")
                        return build

            except KeyError:
                pass
        test_logger("No Build found for specified Tags\n"
                    "Please check if TAGS are specified correctly", "error")
        raise FatalError("No Build selected")
    elif sw_type == "Target":
        for artifact in cm_artifacts:
            if artifact.get("type").upper() == "BUILD":
                build = artifact.get("name").upper()
                test_logger(f"Selected Target SW {build}")
                return build
        raise FatalError("No Target Build selected")
    else:
        raise Exception(f"Wrong sw_type: {sw_type}")


def email_validation(emails: Union[str, list]) -> list:
    if not emails:
        return []
    allowed_domains = ["@nokia.com", "@internal.nsn.com"]
    emails = set(emails.split(",")) if isinstance(emails, str) else set(emails)
    valid_emails = {mail.lstrip() for mail in emails if any(domain in mail for domain in allowed_domains)}
    invalid_emails = emails - valid_emails
    if invalid_emails:
        test_logger(f"Emails not supported: {','.join(invalid_emails)}")
    return list(valid_emails)


def check_if_alarm_exist(admin_conn: object, alarms: Union[int, list]) -> bool:
    """
    Checks if any alarm from the provided list is active on the BTS.
    Args:
        admin_conn (object): Connection object to the BTS.
        alarms (list): A list of alarm IDs to check.
    Returns:
        bool: True if at least one alarm is active, False otherwise.
    """
    try:
        bts_alarms = admin_conn.get_active_alarms(timeout=300)
        return any(fault['faultId'] == alarm for fault in bts_alarms for alarm in alarms)
    except Exception as e:
        test_logger(f"Unexpected error occurred: {e}", "ERROR")
        return False


def get_multiple_target_sw_from_sw_build_tags():
    """
    Retrieves multiple target software builds from SW_BUILD tags.
    Raises:
        Exception: If 'CM_EXECUTION_ID' environment variable is not set.
        FatalError: If no software build tags are found.
    Returns:
        dict: A dictionary where keys are node IDs (e.g., 'node1') and values are software build IDs.
    """
    if not os.environ.get("CM_EXECUTION_ID"):
        raise Exception("Not Cloud Execution, Suite Will be aborted!")
    cm_tags = json.loads(os.getenv("CM_TAGS", "[]"))
    sw_builds_dict = {}
    for cm_tag in cm_tags:
        if cm_tag.split("=")[0] == "SM_BUILD":
            sw_builds_dict[f"node{cm_tag.split(':')[-1]}"] = cm_tag.split("=")[1].split(":")[0]
    if sw_builds_dict:
        return sw_builds_dict
    raise FatalError("No Build selected")


def _serialize_for_json(value):
    """
    Serialize value to JSON-serializable format for logging.
    Handles complex types like callables, large objects, etc.
    """
    if value is None:
        return None
    elif isinstance(value, (str, int, float, bool)):
        return value
    elif isinstance(value, (list, tuple)):
        return [_serialize_for_json(item) for item in value[:10]]  # Limit to first 10 items
    elif isinstance(value, dict):
        return {str(k): _serialize_for_json(v) for k, v in list(value.items())[:20]}  # Limit to first 20 items
    elif callable(value):
        return f"<callable: {getattr(value, '__name__', 'unknown')}>"
    else:
        try:
            str_repr = str(value)
            return str_repr[:200] if len(str_repr) > 200 else str_repr
        except Exception:
            return f"<{type(value).__name__}>"


def _log_keyword_call(local_vars):
    """
    Log keyword call with all arguments for Graylog monitoring.
    Automatically gets function name from call stack.
    """
    try:
        # Get function name from call stack
        keyword_name = inspect.currentframe().f_back.f_code.co_name
        
        # Get Python version
        python_version = f"{sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}"
        
        # Serialize arguments for JSON
        serialized_args = {k: _serialize_for_json(v) for k, v in local_vars.items()}
        
        log_entry = {
            "event_type": "csv4all_keyword_call",
            "keyword_name": keyword_name,
            "python_version": python_version,
            "arguments": serialized_args,
            "timestamp": datetime.utcnow().isoformat() + "Z"
        }
        
        log_message = json.dumps(log_entry, indent=None, ensure_ascii=False, separators=(',', ':'))
        test_logger(f"CSV4ALL_MONITORING: {log_message}", log_level="INFO", console=True)
    except Exception:
        test_logger("CSV4ALL_MONITORING: FETCHING FAILED", log_level="WARN", console=True)
        # If logging fails, don't break execution
        pass
